use stab_bits::BitMatrix;

use super::budget::{
    AlgebraMemoryBudget, StabilizerResource, pauli_bytes, pauli_rows_bytes, plane_bytes,
    tableau_bytes, try_zeroed_words, words_for_bits,
};
use super::tableau::PauliRows;
use super::tableau::rows::multiply_row_into;
use super::{PauliPhase, PauliString, StabilizerError, StabilizerResult, Tableau};

const WORD_BITS: usize = u64::BITS as usize;

/// Returns the row-reduced echelon form of the group generated by `stabilizers`.
///
/// Columns are ordered qubit by qubit, X before Z, and dependent generators are dropped, so the
/// result is unique for the signed stabilizer group. Elimination multiplies whole packed rows, in
/// `O(r n^2 / 64)` word operations for `r` generators over `n` qubits; the working rows are a
/// copy of the input and are reserved fallibly.
pub(crate) fn canonicalize_stabilizers(
    stabilizers: &[PauliString],
) -> StabilizerResult<Vec<PauliString>> {
    let num_qubits = stabilizers.iter().map(PauliString::len).max().unwrap_or(0);
    let mut rows =
        PauliRows::try_zeroed(stabilizers.len(), num_qubits, StabilizerResource::Tableau)?;
    for (row, stabilizer) in stabilizers.iter().enumerate() {
        copy_padded(&mut rows, row, stabilizer)?;
    }
    let half_words = rows.half_words();
    let mut next_pivot = 0;
    for qubit in 0..num_qubits {
        for plane in [0, 1] {
            let word = plane * half_words + qubit / WORD_BITS;
            let mask = 1_u64 << (qubit % WORD_BITS);
            let has_bit = |rows: &PauliRows, row: usize| -> StabilizerResult<bool> {
                Ok(rows
                    .row(row)?
                    .get(word)
                    .is_some_and(|bits| bits & mask != 0))
            };
            let mut pivot = None;
            for row in next_pivot..rows.row_count() {
                if has_bit(&rows, row)? {
                    pivot = Some(row);
                    break;
                }
            }
            let Some(pivot) = pivot else {
                continue;
            };
            for row in 0..rows.row_count() {
                if row != pivot && has_bit(&rows, row)? {
                    multiply_signed_row_into(&mut rows, row, pivot)?;
                }
            }
            rows.swap_rows(next_pivot, pivot)?;
            next_pivot += 1;
        }
    }
    (0..next_pivot).map(|row| rows.to_pauli(row)).collect()
}

/// Synthesizes a tableau whose Z outputs are the independent `stabilizers`, admitted against
/// [`AlgebraMemoryBudget::DEFAULT`].
///
/// See [`stabilizers_to_tableau_with_budget`].
pub fn stabilizers_to_tableau(
    stabilizers: &[PauliString],
    allow_redundant: bool,
    allow_underconstrained: bool,
    inverse: bool,
) -> StabilizerResult<Tableau> {
    stabilizers_to_tableau_with_budget(
        stabilizers,
        allow_redundant,
        allow_underconstrained,
        inverse,
        AlgebraMemoryBudget::DEFAULT,
    )
}

/// Synthesizes a tableau from commuting stabilizer generators, as Stim's `stabilizers_to_tableau`.
///
/// The stabilizers are padded to the widest one's `n` qubits. Gaussian elimination over the
/// transposed stabilizers, one packed row per qubit, applies `H`, `H_YZ`, `XCX`, `XCY`, `XCZ`,
/// `SWAP`, and `X` gates until stabilizer `k` becomes `+Z_k`. The same gates update the tableau
/// `E` of that elimination circuit, held transposed beside the stabilizers so each gate is one
/// word-parallel pass, and the result is `E^-1`, which maps `Z_k` to the `k`-th independent
/// stabilizer and matches Stim's destabilizers and completions exactly; `inverse` returns `E`.
/// Redundant generators are skipped only when `allow_redundant` is set, and fewer than `n`
/// independent generators are completed only when `allow_underconstrained` is set; anticommuting
/// and contradictory generators are refused like Stim. The working rows, the output, and the
/// inversion scratch are admitted against `budget` before allocation. Elimination costs
/// `O(n m (m + n) / 64)` word operations for `m` stabilizers, plus one `O(n^3 / 64)` inversion.
pub fn stabilizers_to_tableau_with_budget(
    stabilizers: &[PauliString],
    allow_redundant: bool,
    allow_underconstrained: bool,
    inverse: bool,
    budget: AlgebraMemoryBudget,
) -> StabilizerResult<Tableau> {
    let num_qubits = stabilizers.iter().map(PauliString::len).max().unwrap_or(0);
    budget.admit(
        StabilizerResource::StabilizerSolve,
        solver_bytes(num_qubits, stabilizers.len()),
    )?;
    let mut solver = Solver::new(stabilizers, num_qubits)?;
    let mut used = 0;
    for (index, stabilizer) in stabilizers.iter().enumerate() {
        for qubit in 0..used {
            if solver.x_bit(qubit, index)? {
                return Err(first_anticommuting_pair(stabilizers));
            }
        }
        let mut pivot = None;
        for qubit in used..num_qubits {
            if solver.x_bit(qubit, index)? || solver.z_bit(qubit, index)? {
                pivot = Some(qubit);
                break;
            }
        }
        let Some(pivot) = pivot else {
            if solver.sign(index)? {
                return Err(StabilizerError::InconsistentStabilizer {
                    stabilizer: stabilizer.to_string(),
                });
            }
            if !allow_redundant {
                return Err(StabilizerError::RedundantStabilizer {
                    stabilizer: stabilizer.to_string(),
                });
            }
            continue;
        };

        if solver.x_bit(pivot, index)? {
            if solver.z_bit(pivot, index)? {
                solver.h_yz(pivot)?;
            } else {
                solver.h(pivot)?;
            }
        }
        for qubit in 0..num_qubits {
            if qubit == pivot {
                continue;
            }
            match (solver.x_bit(qubit, index)?, solver.z_bit(qubit, index)?) {
                (false, false) => {}
                (true, false) => solver.controlled(ControlledGate::Xcx, pivot, qubit)?,
                (false, true) => solver.controlled(ControlledGate::Xcz, pivot, qubit)?,
                (true, true) => solver.controlled(ControlledGate::Xcy, pivot, qubit)?,
            }
        }
        if pivot != used {
            solver.transposed.swap_rows(pivot, used)?;
        }
        if solver.sign(index)? {
            solver.x(used)?;
        }
        used += 1;
    }
    if used < num_qubits && !allow_underconstrained {
        return Err(StabilizerError::UnderconstrainedStabilizers {
            independent: used,
            num_qubits,
        });
    }
    let elimination = solver.into_elimination_tableau()?;
    if inverse {
        Ok(elimination)
    } else {
        elimination.inverse()
    }
}

/// Column where the elimination tableau's generators start: the stabilizer count rounded up to a
/// whole word, so the tableau block can be copied word by word.
fn tableau_column_offset(stabilizer_count: usize) -> usize {
    words_for_bits(stabilizer_count) * WORD_BITS
}

/// Conservative bytes of the solver: the transposed stabilizer and tableau columns with their
/// sign plane, the two transposition matrices of each extracted plane, the elimination tableau,
/// and its inverse with that inversion's scratch.
fn solver_bytes(num_qubits: usize, stabilizer_count: usize) -> u128 {
    let n = num_qubits as u128;
    let columns =
        tableau_column_offset(stabilizer_count).saturating_add(num_qubits.saturating_mul(2));
    let working = pauli_rows_bytes(n, columns) + plane_bytes(1, columns);
    let extraction =
        2 * plane_bytes(n, num_qubits.saturating_mul(2)) + 2 * plane_bytes(2 * n, num_qubits);
    let inversion =
        tableau_bytes(num_qubits) + plane_bytes(n, num_qubits) + 2 * n + pauli_bytes(num_qubits);
    working + extraction + tableau_bytes(num_qubits) + inversion
}

#[derive(Clone, Copy)]
enum ControlledGate {
    Xcx,
    Xcy,
    Xcz,
}

/// Elimination state: one packed `[x | z]` row per qubit whose bit `k < m` belongs to stabilizer
/// `k` and whose bit `offset + j` belongs to generator `j` of the elimination tableau `E`, with
/// one sign plane over all columns. A gate updates every column as a Pauli frame, so stabilizers
/// and `E` advance together.
struct Solver {
    num_qubits: usize,
    offset: usize,
    transposed: PauliRows,
    signs: Vec<u64>,
}

impl Solver {
    fn new(stabilizers: &[PauliString], num_qubits: usize) -> StabilizerResult<Self> {
        let offset = tableau_column_offset(stabilizers.len());
        let columns = offset
            .checked_add(num_qubits.checked_mul(2).ok_or(overflow(num_qubits))?)
            .ok_or(overflow(num_qubits))?;
        let mut transposed =
            PauliRows::try_zeroed(num_qubits, columns, StabilizerResource::StabilizerSolve)?;
        let mut signs =
            try_zeroed_words(StabilizerResource::StabilizerSolve, words_for_bits(columns))?;
        for (index, stabilizer) in stabilizers.iter().enumerate() {
            for (plane, words) in [(0, stabilizer.x_bits()), (1, stabilizer.z_bits())] {
                for_each_set_bit(words, |qubit| transposed.set_plane_bit(qubit, plane, index))?;
            }
            if stabilizer.sign().is_negative() {
                let word = signs
                    .get_mut(index / WORD_BITS)
                    .ok_or(StabilizerError::InvalidStabilizerTableauSynthesis)?;
                *word |= 1_u64 << (index % WORD_BITS);
            }
        }
        for qubit in 0..num_qubits {
            transposed.set_plane_bit(qubit, 0, offset + qubit)?;
            transposed.set_plane_bit(qubit, 1, offset + num_qubits + qubit)?;
        }
        Ok(Self {
            num_qubits,
            offset,
            transposed,
            signs,
        })
    }

    fn bit(&self, qubit: usize, plane: usize, index: usize) -> StabilizerResult<bool> {
        let half_words = self.transposed.half_words();
        let words = self.transposed.row(qubit)?;
        Ok(words
            .get(plane * half_words + index / WORD_BITS)
            .is_some_and(|word| word >> (index % WORD_BITS) & 1 != 0))
    }

    fn x_bit(&self, qubit: usize, index: usize) -> StabilizerResult<bool> {
        self.bit(qubit, 0, index)
    }

    fn z_bit(&self, qubit: usize, index: usize) -> StabilizerResult<bool> {
        self.bit(qubit, 1, index)
    }

    fn sign(&self, index: usize) -> StabilizerResult<bool> {
        self.signs
            .get(index / WORD_BITS)
            .map(|word| word >> (index % WORD_BITS) & 1 != 0)
            .ok_or(StabilizerError::InvalidStabilizerTableauSynthesis)
    }

    fn h(&mut self, qubit: usize) -> StabilizerResult<()> {
        let half_words = self.transposed.half_words();
        let (xs, zs) = self.transposed.row_mut(qubit)?.split_at_mut(half_words);
        for ((s, x), z) in self.signs.iter_mut().zip(xs.iter_mut()).zip(zs.iter_mut()) {
            std::mem::swap(x, z);
            *s ^= *x & *z;
        }
        Ok(())
    }

    fn h_yz(&mut self, qubit: usize) -> StabilizerResult<()> {
        let half_words = self.transposed.half_words();
        let (xs, zs) = self.transposed.row_mut(qubit)?.split_at_mut(half_words);
        for ((s, x), z) in self.signs.iter_mut().zip(xs.iter_mut()).zip(zs.iter_mut()) {
            *x ^= *z;
            *s ^= !*z & *x;
        }
        Ok(())
    }

    fn x(&mut self, qubit: usize) -> StabilizerResult<()> {
        let half_words = self.transposed.half_words();
        let zs = self
            .transposed
            .row(qubit)?
            .get(half_words..)
            .ok_or(StabilizerError::InvalidStabilizerTableauSynthesis)?;
        for (s, z) in self.signs.iter_mut().zip(zs) {
            *s ^= *z;
        }
        Ok(())
    }

    fn controlled(
        &mut self,
        kind: ControlledGate,
        control: usize,
        target: usize,
    ) -> StabilizerResult<()> {
        let half_words = self.transposed.half_words();
        let (first, second) = self.transposed.two_rows_mut(control, target)?;
        let (x1s, z1s) = first.split_at_mut(half_words);
        let (x2s, z2s) = second.split_at_mut(half_words);
        let words = self
            .signs
            .iter_mut()
            .zip(x1s.iter_mut())
            .zip(z1s.iter_mut())
            .zip(x2s.iter_mut())
            .zip(z2s.iter_mut());
        match kind {
            ControlledGate::Xcx => {
                for ((((s, x1), z1), x2), z2) in words {
                    *s ^= (*x1 ^ *x2) & *z1 & *z2;
                    *x1 ^= *z2;
                    *x2 ^= *z1;
                }
            }
            ControlledGate::Xcy => {
                for ((((s, x1), z1), x2), z2) in words {
                    *x1 ^= *x2 ^ *z2;
                    *x2 ^= *z1;
                    *z2 ^= *z1;
                    *s ^= (!*x1 & *z1) & (!*x2 & *z2);
                    *s ^= *x1 & *z1 & (!*z2 & *x2);
                }
            }
            ControlledGate::Xcz => {
                for ((((s, x1), z1), x2), z2) in words {
                    *z2 ^= *z1;
                    *x1 ^= *x2;
                    *s ^= !(*z2 ^ *x1) & (*z1 & *x2);
                }
            }
        }
        Ok(())
    }

    /// Transposes the tableau columns back into generator rows, giving the elimination tableau.
    fn into_elimination_tableau(self) -> StabilizerResult<Tableau> {
        let num_qubits = self.num_qubits;
        let generators = 2 * num_qubits;
        let first_word = self.offset / WORD_BITS;
        let block_words = words_for_bits(generators);
        let source_half = self.transposed.half_words();
        let mut rows =
            PauliRows::try_zeroed(generators, num_qubits, StabilizerResource::StabilizerSolve)?;
        let target_half = rows.half_words();
        if num_qubits == 0 {
            return Ok(Tableau::from_rows(rows));
        }
        for plane in [0, 1] {
            let mut block = BitMatrix::zeros(num_qubits, generators)?;
            for qubit in 0..num_qubits {
                let start = plane * source_half + first_word;
                let source = self
                    .transposed
                    .row(qubit)?
                    .get(start..start + block_words)
                    .ok_or(StabilizerError::InvalidStabilizerTableauSynthesis)?;
                block.row_words_mut(qubit)?.copy_from_slice(source);
            }
            let generator_rows = block.transpose()?;
            drop(block);
            for generator in 0..generators {
                let source = generator_rows.row(generator)?;
                let target = rows
                    .row_mut(generator)?
                    .get_mut(plane * target_half..(plane + 1) * target_half)
                    .ok_or(StabilizerError::InvalidStabilizerTableauSynthesis)?;
                target.copy_from_slice(source.words());
            }
        }
        for generator in 0..generators {
            let column = self.offset + generator;
            let negative = self
                .signs
                .get(column / WORD_BITS)
                .is_some_and(|word| word >> (column % WORD_BITS) & 1 != 0);
            rows.set_sign(generator, negative)?;
        }
        Ok(Tableau::from_rows(rows))
    }
}

const fn overflow(num_qubits: usize) -> StabilizerError {
    StabilizerError::ResourceSizeOverflow {
        resource: StabilizerResource::StabilizerSolve,
        item_count: num_qubits,
        repetitions: 2,
    }
}

/// The first pair `k1 < k2` of anticommuting inputs, reported as Stim does once elimination
/// proves some pair anticommutes.
fn first_anticommuting_pair(stabilizers: &[PauliString]) -> StabilizerError {
    for (first, left) in stabilizers.iter().enumerate() {
        for right in stabilizers.iter().skip(first + 1) {
            if !left.commutes(right).unwrap_or(true) {
                return StabilizerError::AntiCommutingStabilizer {
                    stabilizer: right.to_string(),
                    conflict: left.to_string(),
                };
            }
        }
    }
    StabilizerError::InvalidStabilizerTableauSynthesis
}

/// Right-multiplies row `source` into row `target` of commuting signed rows.
fn multiply_signed_row_into(
    rows: &mut PauliRows,
    target: usize,
    source: usize,
) -> StabilizerResult<()> {
    let half_words = rows.half_words();
    let source_sign = rows.sign(source)?;
    let (target_words, source_words) = rows.row_pair_mut(target, source)?;
    let log_i = multiply_row_into(target_words, source_words, half_words)?;
    if log_i & 1 != 0 {
        return Err(StabilizerError::ImaginaryProduct {
            phase: PauliPhase::from_exponent(log_i),
        });
    }
    let negative = rows.sign(target)? ^ source_sign ^ (log_i == 2);
    rows.set_sign(target, negative)
}

fn copy_padded(rows: &mut PauliRows, row: usize, pauli: &PauliString) -> StabilizerResult<()> {
    let half_words = rows.half_words();
    let words = rows.row_mut(row)?;
    let (xs, zs) = words.split_at_mut(half_words);
    for (target, source) in [(xs, pauli.x_bits()), (zs, pauli.z_bits())] {
        let prefix = target
            .get_mut(..source.len())
            .ok_or(StabilizerError::LengthMismatch {
                left: source.len(),
                right: half_words,
            })?;
        prefix.copy_from_slice(source);
    }
    rows.set_sign(row, pauli.sign().is_negative())
}

fn for_each_set_bit(
    words: &[u64],
    mut visit: impl FnMut(usize) -> StabilizerResult<()>,
) -> StabilizerResult<()> {
    for (word_index, word) in words.iter().copied().enumerate() {
        let mut bits = word;
        while let Some(bit) = bits.lowest_one() {
            visit(word_index * WORD_BITS + bit as usize)?;
            bits &= bits - 1;
        }
    }
    Ok(())
}
